package org.animallink.adoption.infrastructure;
import java.util.*;import java.util.concurrent.TimeUnit;import org.springframework.amqp.core.MessageDeliveryMode;import org.springframework.amqp.rabbit.connection.CorrelationData;import org.springframework.amqp.rabbit.core.RabbitTemplate;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import org.springframework.transaction.support.TransactionTemplate;
@Component @ConditionalOnProperty(name="animallink.messaging.enabled",havingValue="true",matchIfMissing=true) public class AdoptionCompletedOutboxPublisher{private final JdbcTemplate j;private final RabbitTemplate r;private final TransactionTemplate t;public AdoptionCompletedOutboxPublisher(JdbcTemplate j,RabbitTemplate r,TransactionTemplate t){this.j=j;this.r=r;this.t=t;}@Scheduled(fixedDelay=1000) public void publish(){publishBatch();}public int publishBatch(){int n=0;for(String id:j.queryForList("SELECT id FROM outbox_event WHERE status='PENDING' AND available_at<=CURRENT_TIMESTAMP(6) ORDER BY created_at,id LIMIT 20",String.class))if(Boolean.TRUE.equals(t.execute(x->send(id))))n++;return n;}private boolean send(String id){var rows=j.queryForList("SELECT payload_json FROM outbox_event WHERE id=? AND status='PENDING' AND available_at<=CURRENT_TIMESTAMP(6) FOR UPDATE SKIP LOCKED",id);if(rows.isEmpty())return false;try{CorrelationData c=new CorrelationData(id);r.convertAndSend("animallink.domain","adoption.handover.completed",rows.getFirst().get("payload_json").toString(),m->{m.getMessageProperties().setDeliveryMode(MessageDeliveryMode.PERSISTENT);m.getMessageProperties().setContentType("application/json");return m;},c);var ok=c.getFuture().get(5,TimeUnit.SECONDS);if(!ok.isAck())throw new IllegalStateException(ok.getReason());j.update("UPDATE outbox_event SET status='PUBLISHED',published_at=CURRENT_TIMESTAMP(6),last_error=NULL,updated_at=CURRENT_TIMESTAMP(6) WHERE id=? AND status='PENDING'",id);return true;}catch(Exception e){String x=String.valueOf(e.getMessage());j.update("UPDATE outbox_event SET attempt_count=attempt_count+1,last_error=?,available_at=CURRENT_TIMESTAMP(6)+INTERVAL 5 SECOND,updated_at=CURRENT_TIMESTAMP(6) WHERE id=? AND status='PENDING'",x.length()>1000?x.substring(0,1000):x,id);return false;}}}
